(async () => {
  const E = window.__editor; await E.app.ready; await E.ready3d;
  const F = await import('/src/engine/level/LevelFormat.js');
  const C = await import('/src/engine/level/ObjectCatalog.js');
  const K = await import('/src/engine/level/StoryChecks.js');
  const S = await import('/src/editor/story.js');
  const V = await import('/src/editor/visibility.js');
  const Cm = await import('/src/editor/tools/common.js');
  const R = window.R = { E, F, C, K, S, V, Cm, fails: [], orig: F.serializeLevel(E.state.level), msgs: [] };
  R.ok = (c, m) => { if (!c) { R.fails.push(m); setTimeout(() => { throw new Error('ASSERT ' + m); }); } return !!c; };
  // (a step that throws fails the run too: the old code lacks some of the functions used here)
  R.step = async (name, fn) => { try { return await fn(); } catch (e) { R.ok(false, name + ' threw: ' + (e?.message ?? e)); return String(e?.stack ?? e); } };
  R.settle = async () => { await T.sleep(150); while (E.view3d?.busy) await T.sleep(100); await T.sleep(250); };
  R.obj = (id) => E.state.getObject(id);
  E.state.on('status', (m) => R.msgs.push(m));
  R.last = () => R.msgs[R.msgs.length - 1] ?? '';
  R.statusText = () => document.querySelector('.le-status-msg')?.textContent ?? '';
  // the problems under an inspector field, one per line ([] while hidden; null: no such element)
  R.hint = (label) => { const i = T.field(label)?.closest('.le-field')?.querySelector('.le-field-issue'); return !i ? null : i.hidden ? [] : i.textContent.split('\n'); };
  // what Check for problems says about one field of one object
  R.checks = (id, field) => K.storyIssues(E.state.level, S.storyCheckContext(E.state)).filter((i) => i.id === id && i.field === field).map((i) => i.msg);
  R.row = (id) => document.querySelector(`.le-outliner .le-row-item[data-id="${id}"]`);
  R.group = (label) => [...document.querySelectorAll('.le-outliner .le-group')].find((g) => g.querySelector('.le-group-label')?.textContent === label);
  R.set = async (label, v) => { T.setInput(T.field(label), v); await T.sleep(150); return R.hint(label); };
  R.list = () => document.querySelector('.le-outliner-list');
  // the outliner's keyboard item (aria-activedescendant)
  R.act = () => { const id = R.list()?.getAttribute('aria-activedescendant'); return id ? document.getElementById(id) : null; };
  E.state.setTool('select');
  E.state.setView({ layout: 'split', storyPreview: false, storyValues: '', hiddenTypes: [], showObjects: true, showMarkers: true });
  return JSON.stringify({ level: E.state.level.name, bytes: R.orig.length });
})()

