R.step('cost', async () => {
  const { E, S } = R; const st = E.state; const sp = st.level.spawn;
  const nObj = st.level.objects.length;
  const u0 = st._undo.length;
  const talk = [];
  for (let k = 0; k < 40; k++) talk.push(k % 5 === 0 ? `once key-${k}` : `  Rv: line ${k} of the talk, with some words to parse. [if gold > ${k}]`);
  st.begin('villagers');
  const ids = [];
  for (let k = 0; k < 60; k++) ids.push(st.addObject('npc', 3 + (k % 20), 3 + Math.floor(k / 20), { name: `Rv${k}`, talk: talk.map((l) => l.replace('key-', `key-${k}-`)) }, { select: false }).id);
  st.commit();
  const m = st.addObject('marker', sp.x + 1, sp.z + 1, { when: 'met' }, { select: false });
  st.select([m.id]); await T.sleep(300);
  /** @type {Element|null} */ (document.activeElement)?.blur?.();
  const tile = Object.keys(st.level.legend)[0];
  st.begin('Paint');
  // every read of the villagers' scripts counted (a getter on each talk)
  let reads = 0;
  for (const id of ids) {
    const o = R.obj(id); let v = o.talk;
    Object.defineProperty(o, 'talk', { get() { reads++; return v; }, set(x) { v = x; }, enumerable: true, configurable: true });
  }
  const out = {};
  // a stroke's frames (terrain only), the inspector refreshed each time, a condition without done: keys
  reads = 0;
  for (let k = 0; k < 10; k++) { st.editTiles([{ i: 2 + k, j: 2, tile }]); E.app.inspector.refresh(); }
  out.flagOnly = reads;
  R.ok(reads === 0, 'a condition without done: keys reads no script of the level, also inside a stroke');
  // with done: keys: the level's own keys once, then cached through the stroke
  st.updateObject(m.id, (o) => { o.when = 'done:key-new'; }); E.app.inspector.refresh();
  out.doneHint = R.hint('Story: only when');
  R.ok(out.doneHint?.length === 1 && /done:key-new names no/.test(out.doneHint[0]), 'done: of nothing: the hint warns');
  reads = 0;
  for (let k = 0; k < 10; k++) { st.editTiles([{ i: 2 + k, j: 3, tile }]); E.app.inspector.refresh(); }
  out.done = reads;
  R.ok(reads === 0, 'its keys are read once, not again on every stroke frame');
  // an object change inside the stroke: read again, and right
  reads = 0;
  st.updateObject(ids[3], (o) => { o.talk = [...o.talk, 'once key-new', '  : hi']; }); E.app.inspector.refresh();
  out.afterEdit = reads;
  out.afterHint = R.hint('Story: only when');
  R.ok(reads > 0 && reads <= 3 * ids.length && out.afterHint?.length === 0, 'an object edit inside the stroke: the keys are read again (once) — done:key-new now names a once block');
  out.ms = (() => { const t0 = performance.now(); for (let k = 0; k < 50; k++) S.conditionIssues(st, R.obj(m.id), 'when', 'met and not gone'); return +((performance.now() - t0) / 50).toFixed(3); })();
  st.cancel(); await T.sleep(100);
  while (st.canUndo && st._undo.length > u0) st.undo();
  R.ok(st.level.objects.length === nObj, 'the villagers and the marker removed again');
  return JSON.stringify(out);
})

