  // (a) the campaign's context not there yet (campaign.json held back): a campaign level, its events unknown
  let release; const gate = new Promise((r) => { release = r; });
  window.fetch = async (u, o) => (/\/campaigns\/ferrymans-lantern\/campaign\.json/.test(String(u)) ? (await gate, real(u, o)) : real(u, o));
  try {
    await E.app.openProject('mill-road', { confirm: false, campaign: 'ferrymans-lantern' }); await E.ready3d;
    const sp = st.level.spawn;
    const m = st.addObject('marker', sp.x + 2, sp.z, { when: 'done:millbrook.ev_planks', unless: 'visited:old-quarry' }, { select: false });
    R.m = m.id;
    st.select([m.id]); await T.sleep(300);
    R.ok(S.cachedStoryContext('ferrymans-lantern') === undefined, 'the campaign\'s context has not arrived');
    out.a = { when: R.hint(W), checks: R.checks(m.id, 'when'), soft: E.app._softWarnings().filter((l) => l.includes(m.id)) };
    R.ok(out.a.when?.length === 0 && out.a.checks.length === 0 && out.a.soft.length === 0, 'meanwhile done:millbrook.ev_planks is not reported (a campaign level, its events not known yet)');
    R.ok(R.hint(U)?.length === 0, '…nor visited:old-quarry');
    out.a.call = E.app._softWarnings().filter((l) => l.includes('"call" needs') || l.includes('is not in the story files'));
    R.ok(out.a.call.length === 0, 'nor a call of a story script (the campaign may have it)');
  } finally { release(); window.fetch = real; }
  await S.campaignStoryContext('ferrymans-lantern'); await T.sleep(300);
  R.ok(!!S.cachedStoryContext('ferrymans-lantern')?.files, 'the context arrived');
  R.ok(R.hint(W)?.length === 0, 'done:millbrook.ev_planks: a once event of the campaign');
  // (b) a level of the campaign changed since it was read (saved from this editor, say): opening a
  // level of the campaign reads them again
  const text = await real('/campaigns/ferrymans-lantern/levels/millbrook.json', { cache: 'no-store' }).then((x) => x.text());
  const { level } = F.parseLevel(text);
  F.addObject(level, 'event', 10, 10, { minX: 9, maxX: 11, minZ: 9, maxZ: 11, on: 'use', once: true, run: ['toast new'] }).id = 'ev_new';
  const changed = F.serializeLevel(level);
  window.fetch = async (u, o) => (/\/campaigns\/ferrymans-lantern\/levels\/millbrook\.json/.test(String(u)) ? new Response(changed, { status: 200, headers: { 'content-type': 'application/json' } }) : real(u, o));
  try {
    await E.app.openProject('mill-road', { confirm: false, campaign: 'ferrymans-lantern' }); await E.ready3d;
    await S.campaignStoryContext('ferrymans-lantern'); await T.sleep(300);
  } finally { window.fetch = real; }
  const sp = st.level.spawn;
  const m = st.addObject('marker', sp.x + 2, sp.z, { when: 'done:millbrook.ev_new', unless: 'item:plank > 2' }, { select: false });
  R.m = m.id;
  st.select([m.id]); await T.sleep(300);
  out.b = { when: R.hint(W), checks: R.checks(m.id, 'when') };
  R.ok(out.b.when?.length === 0 && out.b.checks.length === 0, 'opening a level of the campaign reads its levels again: millbrook\'s new once event is known');
  // (c) a read that fails keeps the context read before
  const good = S.cachedStoryContext('ferrymans-lantern');
  window.fetch = async (u, o) => (/\/campaigns\/ferrymans-lantern\/campaign\.json/.test(String(u)) ? new Response('nope', { status: 404 }) : real(u, o));
  let got;
  try { got = await S.campaignStoryContext('ferrymans-lantern', { refresh: true }); await T.sleep(300); } finally { window.fetch = real; }
  R.ok(!!good && got === good && S.cachedStoryContext('ferrymans-lantern') === good, 'campaign.json unreadable on a refresh: the context read before is kept');
  R.ok(R.hint(W)?.length === 0 && R.hint(U)?.length === 0, 'and the hints with it');
  // (d) a story file that cannot be read: nothing the story files declare is checked (all or nothing)
  await S.campaignStoryContext('ferrymans-lantern', { refresh: true }); await T.sleep(300);
  R.ok(R.hint(U)?.length === 0, 'item:plank is declared');
  let h = await R.set(U, 'item:nope-s4 > 2');
  R.ok(h?.length === 1 && /item "nope-s4" is not declared/.test(h[0]), 'an undeclared item is reported');
  window.fetch = async (u, o) => (/\/campaigns\/ferrymans-lantern\/story\/main\.json/.test(String(u)) ? new Response('nope', { status: 404 }) : real(u, o));
  try { await S.campaignStoryContext('ferrymans-lantern', { refresh: true }); await T.sleep(300); } finally { window.fetch = real; }
  const c = S.cachedStoryContext('ferrymans-lantern');
  out.d = { items: c?.items ? [...c.items] : null, quests: !!c?.quests, scripts: !!c?.scripts, actors: !!c?.actors, events: !!c?.files };
  R.ok(!!c && !c.items && !c.quests && !c.scripts && !c.actors && !c.files && c.levels instanceof Set, 'main.json unreadable: no items, quests, scripts, actors or events (the levels still)');
  h = await R.set(U, 'item:plank > 2');
  R.ok(h?.length === 0 && R.checks(m.id, 'unless').length === 0, 'so item:plank is not reported as undeclared');
  h = await R.set(U, 'item:nope-s4 > 2');
  R.ok(h?.length === 0, '…nor any item');
  await S.campaignStoryContext('ferrymans-lantern', { refresh: true }); await T.sleep(300);
  out.restored = R.hint(U);
  R.ok(out.restored?.length === 1, 'read again: the undeclared item is reported again');
  let n = 0; while (st.canUndo && n < 50) { st.undo(); n++; }
  const file = await real('/campaigns/ferrymans-lantern/levels/mill-road.json', { cache: 'no-store' }).then((r) => r.text());
  R.ok(R.F.serializeLevel(st.level) === file && !st.dirty, 'Mill Road as its file');
  return JSON.stringify(out);
})

R.step('saveAs', async () => {
  const { E, S } = R; const st = E.state;
  const LS = await import('/src/engine/level/LevelStorage.js');
  await E.app.openProject('emberfall', { confirm: false }); await E.ready3d; await R.settle();
  const sp = st.level.spawn;
  const out = {};
  const t = st.addObject('tree', sp.x + 2.5, sp.z + 4, { when: 'level = emberfall' }, { select: false });
  E.view2d.focusOn(t.x, t.z, { scale: 36 });
  st.setView({ storyPreview: true, storyValues: '' }); await R.settle();
  st.select([t.id]); await T.sleep(100);
  R.ok(JSON.stringify(st.selection) === JSON.stringify([t.id]) && E.view2d._visible(R.obj(t.id)), 'level = emberfall holds in Emberfall: shown and selected');
  try {
    await E.app._saveTo('local', 'zz-story4-slot'); await R.settle();
    out.msg = R.last();
    R.ok(st.fileRef.kind === 'local' && st.fileRef.name === 'zz-story4-slot', 'saved into a browser slot');
    R.ok(!st.selection.includes(t.id), 'its level is the slot now: the preview hides the tree, which leaves the selection');
    R.ok(R.last().startsWith('Saved in this browser') && R.last().includes(`${t.id} left the selection: hidden by the story preview (no values)`), 'the save message says so');
    R.ok(E.view2d._visible(R.obj(t.id)) === false && E.view3d.props.hiddenIds.has(t.id) && !!R.row(t.id)?.classList.contains('is-hidden'), 'the 2D map, the 3D view and the outliner follow at once');
    const n0 = st.level.objects.length;
    E.app.run('edit.delete'); await T.sleep(100);
    R.ok(st.level.objects.length === n0 && !!R.obj(t.id), 'Delete removes nothing');
  } finally {
    try { LS.deleteLocalLevel('zz-story4-slot'); } catch { /* gone */ }
  }
  R.ok(!LS.listLocalLevels().some((l) => l.slot === 'zz-story4-slot'), 'the slot deleted again');
  // its file now in a campaign (the reference only: nothing is written): the campaign's context is
  // read, and the condition hint follows
  st.setView({ storyPreview: false }); await R.settle();
  const m = st.addObject('marker', sp.x + 4, sp.z + 2, { when: 'done:millbrook.ev_planks' }, { select: false });
  st.select([m.id]); await T.sleep(300);
  const h0 = out.single = R.hint('Story: only when');
  R.ok(h0?.length === 1 && /of this level/.test(h0[0]), 'a single level: done:millbrook.ev_planks names nothing of this level');
  const before = { ...st.fileRef };
  st.markSaved({ kind: 'project', name: 'zz-story4', campaign: 'ferrymans-lantern' });
  E.app._fileRefChanged(before);
  await S.campaignStoryContext('ferrymans-lantern'); await T.sleep(300);
  const h1 = out.campaign = R.hint('Story: only when');
  R.ok(h1?.length === 0 && R.checks(m.id, 'when').length === 0, 'in the campaign: its context is read, the hint follows (a once event of millbrook)');
  // (the document is thrown away: Emberfall again from its file)
  await E.app.openProject('emberfall', { confirm: false }); await E.ready3d; await R.settle();
  R.ok(R.F.serializeLevel(st.level) === R.orig && !st.dirty && st.fileRef.kind === 'project' && st.fileRef.name === 'emberfall', 'Emberfall as its file');
  return JSON.stringify(out);
})
